type State =
  | { status: 'loading' }
  | { status: 'success'; data: string[] }
  | { status: 'error'; message: string };

function describe(s: State): string {
  switch (s.status) {
    case 'loading':
      return '...';
    case 'success':
      return `${s.data.length} items`;
    case 'error':
      return `Error: ${s.message}`;
  }
}

const states: State[] = [
